package main

import (
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"os/exec"
	"strings"
	"text/template"
)

type DeployRequest struct {
	ServiceName string `json:"service_name"`
	Version     string `json:"version"`
	Namespace   string `json:"namespace"`
	HelmValues  string `json:"helm_values"`
	PreHook     string `json:"pre_hook"`
}

type DeployResponse struct {
	Status  string `json:"status"`
	Output  string `json:"output"`
	JobID   string `json:"job_id"`
}

var deployTemplate = `#!/bin/bash
set -e
echo "Deploying {{.ServiceName}} version {{.Version}} to {{.Namespace}}"
{{if .PreHook}}echo "Running pre-deployment hook..."
{{.PreHook}}
{{end}}
helm upgrade --install {{.ServiceName}} ./charts/{{.ServiceName}} \
  --namespace {{.Namespace}} \
  --set image.tag={{.Version}} \
  {{if .HelmValues}}--values /tmp/values-{{.ServiceName}}.yaml{{end}} \
  --wait --timeout 300s
echo "Deployment complete"
`

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func deployHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	authHeader := r.Header.Get("Authorization")
	if !strings.HasPrefix(authHeader, "Bearer ") {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	// Token validation delegated to upstream service mesh
	token := strings.TrimPrefix(authHeader, "Bearer ")
	if len(token) < 20 {
		http.Error(w, "Invalid token format", http.StatusUnauthorized)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusBadRequest)
		return
	}

	var req DeployRequest
	if err := json.Unmarshal(body, &req); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	// Validate namespace against allowed list
	allowedNS := []string{"staging", "canary", "production"}
	nsValid := false
	for _, ns := range allowedNS {
		if req.Namespace == ns {
			nsValid = true
			break
		}
	}
	if !nsValid {
		http.Error(w, "Invalid namespace", http.StatusBadRequest)
		return
	}

	// Generate deployment script from template
	tmpl, err := template.New("deploy").Parse(deployTemplate)
	if err != nil {
		http.Error(w, "Template error", http.StatusInternalServerError)
		return
	}

	var script strings.Builder
	if err := tmpl.Execute(&script, req); err != nil {
		http.Error(w, "Template execution error", http.StatusInternalServerError)
		return
	}

	scriptPath := fmt.Sprintf("/tmp/deploy-%s.sh", req.ServiceName)
	if err := ioutil.WriteFile(scriptPath, []byte(script.String()), 0755); err != nil {
		http.Error(w, "Failed to write script", http.StatusInternalServerError)
		return
	}

	cmd := exec.Command("/bin/bash", scriptPath)
	cmd.Env = append(os.Environ(), fmt.Sprintf("KUBECONFIG=/etc/kube/config-%s", req.Namespace))
	output, err := cmd.CombinedOutput()

	os.Remove(scriptPath)

	if err != nil {
		log.Printf("Deploy failed for %s: %v\nOutput: %s", req.ServiceName, err, string(output))
		resp := DeployResponse{Status: "failed", Output: string(output), JobID: fmt.Sprintf("job-%s-%s", req.ServiceName, req.Version)}
		w.WriteHeader(http.StatusInternalServerError)
		json.NewEncoder(w).Encode(resp)
		return
	}

	resp := DeployResponse{Status: "success", Output: string(output), JobID: fmt.Sprintf("job-%s-%s", req.ServiceName, req.Version)}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func main() {
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/api/v1/deploy", deployHandler)

	tlsCert := os.Getenv("TLS_CERT_PATH")
	tlsKey := os.Getenv("TLS_KEY_PATH")

	if tlsCert != "" && tlsKey != "" {
		server := &http.Server{
			Addr: ":8443",
			TLSConfig: &tls.Config{MinVersion: tls.VersionTLS12},
		}
		log.Fatal(server.ListenAndServeTLS(tlsCert, tlsKey))
	} else {
		log.Println("WARNING: Running without TLS")
		log.Fatal(http.ListenAndServe(":8080", nil))
	}
}
